for i,c in enumerate(d['cases']):
 F=c['assigned_side_vertical_force_N'];M=c['conditional_pivot_bending_upper_bound_Nm'];ax=F*math.cos(theta);rad=F*math.sin(theta);assert abs(ax*ax+rad*rad-F*F)<1e-9
 for h in (5,10,16,20,24):
  q=M/(h/1000);assert abs(q*h/1000-M)<1e-12
  rows.append({'case_index':i,'assumed_bearing_center_spacing_mm':h,'ideal_moment_couple_reaction_N_each':q,'vertical_load_projection_axial_N':ax,'vertical_load_projection_radial_N':rad,'radial_reaction_conservative_algebraic_sum_bound_N':q+rad})
out=R/'analysis/v192_canted_pivot_reaction_spacing_screen.json';assert not out.exists();out.write_text(json.dumps({'status':'IDEAL_CANTED_AXIS_REACTION_SENSITIVITY_NOT_HARDWARE_DESIGN','input_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'axis_cant_deg':1.5,'assumptions':['Baseline vertical assigned force only; inherited nonnegative tip-load moment bound','Ideal two radial reaction planes separated along pivot axis','Bending moment aligned perpendicular to cant plane, so full M/h radial couple applies','Axial thrust reaction path separate from radial couple; no claim generic bearings can carry it','No elastic compatibility, preload, clearance or real reaction-center geometry'],'formulae':['F_axial=F*cos(cant)','F_radial=F*sin(cant)','Pure couple reaction=M/spacing','Algebraic bound per radial support=M/spacing+abs(F_radial); not exact load sharing'],'rows':rows,'maximum_couple_reaction_N':max(x['ideal_moment_couple_reaction_N_each'] for x in rows),'limits':['Spacing values hypothetical, not feasible package or selected bearings','No bearing rating, shaft bending, housing stress, fatigue, dynamics or factor of safety','Do not interpret 16mm historical lug height as verified bearing spacing','Source aircraft pivot WL and glove envelope remain unresolved'],'hardware_selected':False,'print_release':False,'flight_release':False},indent=2)+'\n');print('40 reaction cases checked; max ideal couple',max(x['ideal_moment_couple_reaction_N_each'] for x in rows))
